using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace GearLab {public static class Reference67ViewTests {
 static int checks;static void Check(bool v,string m){checks++;if(!v)throw new Exception(m);}
 static void Wait(Func<bool> f,string m){var s=System.Diagnostics.Stopwatch.StartNew();while(!f()&&s.Elapsed.TotalSeconds<120){Application.DoEvents();Thread.Sleep(20);}Check(f(),m);}
 static T Get<T>(Task<T> t){Wait(()=>t.IsCompleted,"viewport response");return t.GetAwaiter().GetResult();}
 static void Shot(RobotDesignerForm r,string path){var until=DateTime.UtcNow.AddMilliseconds(600);Wait(()=>DateTime.UtcNow>until,"render settled");var task=r.WebScene.SavePreview(path);Wait(()=>task.IsCompleted,"preview saved");task.GetAwaiter().GetResult();}
 public static int Run(string folder){Directory.CreateDirectory(folder);var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};string root=Path.GetDirectoryName(Application.ExecutablePath);string file=Path.Combine(root,"examples","Reference67.robot.json");if(!File.Exists(file))file=Path.Combine(Path.GetDirectoryName(root),"examples","Reference67.robot.json");var d=RobotDocument.Parse(File.ReadAllText(file));
 Check(d.Joints.Count==6&&d.Joints.All(j=>j.BodyGenerator.Variant=="Reference67"&&!j.BodyGenerator.BlenderDesign),"six independent parametric mechanisms");Check(d.Joints.All(j=>j.GeneratedBody!=null&&j.GeneratedBody.Result.GeometryValid&&j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(d,j,j.BodyGenerator)),"all native CAD caches valid and current");var b=RobotCad.Build(d);Check(b.Model.Valid,"assembled model valid");Check(RobotConnections.Validate(b).Count==0,"all mechanical flange ports mate");
 var pose=d.Clone();double[] q={0,20,-35,15,-20,25};for(int i=0;i<6;i++)pose.Joints[i].Position=q[i];var pb=RobotCad.Build(pose);Check(RobotConnections.Validate(pb).Count==0,"bent pose maintains all flange ports");
 using(var r=new RobotDesignerForm())using(var shell=new WorkspaceShell(r)){r.SetDocument(d);shell.Show();Wait(()=>r.WebScene.Ready&&r.Scene.Ready,"native viewport ready");int parts=r.Build.Entries.Values.Count(e=>!e.Guide);Wait(()=>{string t=CADDocument.Serializer().Deserialize<string>(Get(r.WebScene.Inspect()));return t.Contains("\"parts\":"+parts)&&t.Contains("triangles");},"actual CAD meshes loaded");r.SetStage(2);r.WebScene.Send(new{type="presentation",enabled=true});r.WebScene.Send(new{type="preset",view="REFERENCE"});Shot(r,Path.Combine(folder,"reference67-upright.png"));r.SetDocument(pose);Wait(()=>r.Scene.Ready,"bent CAD view ready");r.WebScene.Send(new{type="presentation",enabled=true});r.WebScene.Send(new{type="preset",view="REFERENCE"});Shot(r,Path.Combine(folder,"reference67-bent.png"));r.OpenJointControllers();int meshes=r.Scene.MeshBuildCount;var before=r.Build.Current[pose.Joints[2].Id].Origin;r.JogJoint(pose.Joints[1].Id,5);Check((r.Build.Current[pose.Joints[2].Id].Origin-before).Length>1,"child follows articulated engineering joint");Check(r.Scene.MeshBuildCount==meshes,"jog avoids remeshing");Check(r.ControllerCount==6,"six joint controllers");Shot(r,Path.Combine(folder,"reference67-controls.png"));shell.ApproveTestClose();shell.Close();}
 File.WriteAllText(Path.Combine(folder,"reference67-view-results.txt"),"PASS "+checks+" assertions: independent editable CAD, current native bodies, flange mating, actual viewport, articulated pose and controllers.",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reference67-view-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{AppSettings.Current=old;}}
}}
